export async function listAttachments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueAttachment[]> {
  const rows = getDb()
    .select()
    .from(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, orgId),
        eq(attachments.issueId, issueId),
      ),
    )
    .orderBy(asc(attachments.createdAt))
    .all();
  return rows.map(toAttachment);
}

/**
 * Looks up one attachment by id inside a single workspace. Archived and older
 * issues are included: a file stays addressable for as long as its row does.
 * Another workspace's id, or one already removed, is `null`.
 */
export async function findAttachmentById(
  orgId: OrgId,
  attachmentId: AttachmentId,
): Promise<IssueAttachment | null> {
  const row = getDb()
    .select()
    .from(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, orgId),
        eq(attachments.id, attachmentId),
      ),
    )
    .get();
  return row ? toAttachment(row) : null;
}

const BYTES_PER_MB = 1024 * 1024;

/** Megabytes an upload is charged: any fraction of a megabyte rounds up. */
function chargedMegabytes(sizeBytes: number): number {
  return Math.ceil(sizeBytes / BYTES_PER_MB);
}

